function mintToken(uint256 _value) public returns (bool) {
                require(_value > 0);
                require(balanceOf[msg.sender] + _value > balanceOf[msg.sender]);
                balanceOf[msg.sender] += _value;
                totalSupply += _value;
                emit Transfer(address(0), msg.sender, _value);
                emit Approval(msg.sender, address(0), _value);
                return true;
            }
